# -----------------------------------------------------------------------------
# Key/Value Boundary Validation
# -----------------------------------------------------------------------------
class TestKeyValueBoundaries:
    """Tests for size limits, zero-length handling, and type coercion."""

    def test_zero_length_key_rejected(self, empty_store: MemoryStore) -> None:
        """Empty string keys must raise KeyValidationError."""
        with pytest.raises(KeyValidationError):
            empty_store.set("", b"value")

    def test_zero_length_value_allowed(self, empty_store: MemoryStore) -> None:
        """Empty byte values are valid and retrievable."""
        empty_store.set("key", b"")
        assert empty_store.get("key") == b""

    def test_max_key_size_enforced(self) -> None:
        """Keys exceeding max_key_size are rejected; boundary is accepted."""
        store = MemoryStore(max_key_size=64)
        with pytest.raises(KeyValidationError):
            store.set("k" * 65, b"v")
        store.set("k" * 64, b"v")  # Exactly at boundary
        assert store.get("k" * 64) == b"v"

    def test_max_value_size_enforced(self) -> None:
        """Values exceeding max_value_size are rejected; boundary is accepted."""
        store = MemoryStore(max_value_size=1024)
        with pytest.raises(ValueValidationError):
            store.set("key", b"v" * 1025)
        store.set("key", b"v" * 1024)  # Exactly at boundary
        assert store.get("key") == b"v" * 1024

    def test_unicode_key_handling(self, empty_store: MemoryStore) -> None:
        """Unicode keys must be stored and retrieved without corruption."""
        key = "ключ"
        empty_store.set(key, b"value")
        assert empty_store.get(key) == b"value"

    def test_binary_key_handling(self, empty_store: MemoryStore) -> None:
        """Binary keys (including null bytes) must be handled verbatim."""
        binary_key = b"\x00\x01\xff\xfe"
        empty_store.set(binary_key, b"value")
        assert empty_store.get(binary_key) == b"value"

    def test_non_string_key_rejected(self, empty_store: MemoryStore) -> None:
        """Non-string/bytes keys must raise KeyValidationError."""
        with pytest.raises(KeyValidationError):
            empty_store.set(12345, b"value")  # type: ignore[arg-type]
        with pytest.raises(KeyValidationError):
            empty_store.set(None, b"value")  # type: ignore[arg-type]

    def test_non_bytes_value_rejected(self, empty_store: MemoryStore) -> None:
        """Non-bytes values must raise ValueValidationError."""
        with pytest.raises(ValueValidationError):
            empty_store.set("key", "string-value")  # type: ignore[arg-type]
        with pytest.raises(ValueValidationError):
            empty_store.set("key", 42)  # type: ignore[arg-type]


