# Core CRUD Operations
# -----------------------------------------------------------------------------
class TestCoreOperations:
    """Tests for get, set, delete, and existence semantics."""

    def test_missing_key_returns_none(self, empty_store: MemoryStore) -> None:
        """Retrieving a non-existent key must return None."""
        assert empty_store.get("missing") is None

    def test_set_and_get_roundtrip(self, empty_store: MemoryStore) -> None:
        """Basic set/get roundtrip must return the exact stored value."""
        empty_store.set("key", b"payload")
        assert empty_store.get("key") == b"payload"

    def test_overwrite_existing_key(self, empty_store: MemoryStore) -> None:
        """Setting an existing key must overwrite the previous value."""
        empty_store.set("key", b"first")
        empty_store.set("key", b"second")
        assert empty_store.get("key") == b"second"

    def test_delete_existing_key(self, populated_store: MemoryStore) -> None:
        """Deleting an existing key must remove it and return True."""
        assert populated_store.delete("alpha") is True
        assert populated_store.get("alpha") is None

    def test_delete_missing_key(self, empty_store: MemoryStore) -> None:
        """Deleting a non-existent key must return False (or raise)."""
        # Contract: return False for idempotent deletion
        assert empty_store.delete("ghost") is False

    def test_exists_after_set(self, empty_store: MemoryStore) -> None:
        """Exists must return True immediately after a set operation."""
        empty_store.set("present", b"data")
        assert empty_store.exists("present") is True

    def test_exists_after_delete(self, populated_store: MemoryStore) -> None:
        """Exists must return False after a delete operation."""
        populated_store.delete("beta")
        assert populated_store.exists("beta") is False

    def test_exists_missing_key(self, empty_store: MemoryStore) -> None:
        """Exists must return False for keys never inserted."""
        assert empty_store.exists("absent") is False


