# State Management & Enumeration
# -----------------------------------------------------------------------------
class TestStateManagement:
    """Tests for store-wide operations: size, keys, clear, and isolation."""

    def test_size_tracks_insertions(self, empty_store: MemoryStore) -> None:
        """Size must reflect the number of unique keys."""
        assert empty_store.size() == 0
        empty_store.set("a", b"1")
        empty_store.set("b", b"2")
        assert empty_store.size() == 2

    def test_size_after_overwrite(self, empty_store: MemoryStore) -> None:
        """Overwriting a key must not increase the store size."""
        empty_store.set("a", b"1")
        empty_store.set("a", b"2")
        assert empty_store.size() == 1

    def test_size_after_delete(self, populated_store: MemoryStore) -> None:
        """Deleting a key must decrement the store size."""
        initial_size = populated_store.size()
        populated_store.delete("alpha")
        assert populated_store.size() == initial_size - 1

    def test_keys_enumeration(self, populated_store: MemoryStore) -> None:
        """Keys must return a set-like collection of all stored keys."""
        keys = populated_store.keys()
        assert set(keys) == {"alpha", "beta", "gamma"}

    def test_keys_empty_store(self, empty_store: MemoryStore) -> None:
        """Keys must return an empty collection for a fresh store."""
        assert empty_store.keys() == []

    def test_clear_empties_store(self, populated_store: MemoryStore) -> None:
        """Clear must remove all entries and reset size to zero."""
        populated_store.clear()
        assert populated_store.size() == 0
        assert populated_store.keys() == []
        assert populated_store.get("alpha") is None

    def test_instance_isolation(self) -> None:
        """Separate store instances must not share state."""
        store_a = MemoryStore()
        store_b = MemoryStore()
        store_a.set("shared", b"a")
        assert store_b.get("shared") is None
        assert store_b.size() == 0


