class TestEdgeCases:
    """Tests for unusual but valid inputs and error propagation."""

    def test_large_binary_value_roundtrip(self, empty_store: MemoryStore) -> None:
        """Large binary payloads (within limits) must roundtrip intact."""
        payload = bytes(range(256)) * 100  # 25,600 bytes
        empty_store.set("blob", payload)
        assert empty_store.get("blob") == payload

    def test_key_with_whitespace(self, empty_store: MemoryStore) -> None:
        """Keys with leading/trailing whitespace must be preserved exactly."""
        key = "  spaced key  "
        empty_store.set(key, b"v")
        assert empty_store.get(key) == b"v"
        assert empty_store.get("spaced key") is None  # Not trimmed

    def test_case_sensitivity(self, empty_store: MemoryStore) -> None:
        """Keys must be case-sensitive."""
        empty_store.set("Key", b"upper")
        empty_store.set("key", b"lower")
        assert empty_store.get("Key") == b"upper"
        assert empty_store.get("key") == b"lower"

    def test_validation_error_types(self) -> None:
        """Validation errors must be distinct and catchable."""
        store = MemoryStore()
        with pytest.raises(KeyValidationError):
            store.set("", b"v")
        with pytest.raises(ValueValidationError):
            store.set("k", "not-bytes")  # type: ignore[arg-type]

    def test_custom_limits_are_respected(self) -> None:
        """Custom max sizes must be enforced per-instance."""
        small_store = MemoryStore(max_key_size=4, max_value_size=8)
        with pytest.raises(KeyValidationError):
            small_store.set("toolong", b"v")
        with pytest.raises(ValueValidationError):
            small_store.set("k", b"toolongvalue")
        small_store.set("k", b"ok")
        assert small_store.get("k") == b"ok"